<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import ModalDialog from './ModalDialog.vue';
import {initialIconCrop,moveIconCrop,resizeIconCrop,renderIconCrop,type IconCrop} from '../design/icon-crop.ts';
import {normalizeHex} from '../design/waveform-color.ts';
const props=defineProps<{url:string;name:string;busy:boolean;saveError?:string}>();
const emit=defineEmits<{close:[];pick:[];apply:[dataUrl:string]}>();
const image=ref<HTMLImageElement>(),preview=ref<HTMLCanvasElement>(),crop=ref<IconCrop>({x:0,y:0,width:1,height:1}),shape=ref('square'),ready=ref(false),error=ref('');
const removeBackground=ref(false),backgroundColor=ref('#ffffff'),tolerance=ref(12),sampling=ref(false),colorDraft=ref('#ffffff');
const removal=computed(()=>({enabled:removeBackground.value,color:backgroundColor.value,tolerance:tolerance.value}));
const ratio=computed(()=>shape.value==='square'?1:shape.value==='landscape'?4/3:shape.value==='portrait'?3/4:shape.value==='original'&&image.value?image.value.naturalWidth/image.value.naturalHeight:null);
const selection=computed(()=>{const i=image.value;if(!i||!ready.value)return {};const c=crop.value;return {left:c.x/i.naturalWidth*100+'%',top:c.y/i.naturalHeight*100+'%',width:c.width/i.naturalWidth*100+'%',height:c.height/i.naturalHeight*100+'%'};});
function reset(){const i=image.value;if(!i)return;crop.value=initialIconCrop(i.naturalWidth,i.naturalHeight,ratio.value);}
function loaded(){ready.value=true;error.value='';shape.value='square';reset();draw();}
function draw(){if(!ready.value||!image.value||!preview.value)return;try{renderIconCrop(image.value,crop.value,preview.value,removal.value);}catch(e){error.value=e instanceof Error?e.message:'预览失败。';}}
watch(crop,draw,{deep:true});watch(shape,()=>{if(ready.value)reset();});watch(()=>props.url,()=>{ready.value=false;});
watch(removal,draw);watch(backgroundColor,value=>colorDraft.value=value);
function setColor(value:string){const color=normalizeHex(value);if(!color){error.value='请输入有效的背景 HEX 颜色。';return;}backgroundColor.value=color;removeBackground.value=true;error.value='';}
function sample(event:MouseEvent){if(!sampling.value||!image.value)return;event.preventDefault();event.stopPropagation();const i=image.value,b=i.getBoundingClientRect(),x=Math.max(0,Math.min(i.naturalWidth-1,Math.floor((event.clientX-b.left)/b.width*i.naturalWidth))),y=Math.max(0,Math.min(i.naturalHeight-1,Math.floor((event.clientY-b.top)/b.height*i.naturalHeight))),c=document.createElement('canvas');c.width=c.height=1;const ctx=c.getContext('2d');if(!ctx)return;ctx.drawImage(i,x,y,1,1,0,0,1,1);const pixel=ctx.getImageData(0,0,1,1).data;if(!pixel[3]){error.value='这里已经透明，请选择有颜色的背景。';return;}setColor('#'+Array.from(pixel.slice(0,3)).map(v=>v.toString(16).padStart(2,'0')).join(''));sampling.value=false;}
let drag:{x:number;y:number;crop:IconCrop;resize:boolean;id:number}|undefined;
function down(event:PointerEvent,resize=false){if(props.busy||sampling.value||!ready.value||event.button!==0)return;event.preventDefault();event.stopPropagation();drag={x:event.clientX,y:event.clientY,crop:{...crop.value},resize,id:event.pointerId};(event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);}
function move(event:PointerEvent){if(!drag||event.pointerId!==drag.id||!image.value)return;const i=image.value,b=i.getBoundingClientRect(),dx=(event.clientX-drag.x)*i.naturalWidth/b.width,dy=(event.clientY-drag.y)*i.naturalHeight/b.height;
 crop.value=drag.resize?resizeIconCrop(drag.crop,drag.crop.width+dx,drag.crop.height+dy,i.naturalWidth,i.naturalHeight,ratio.value):moveIconCrop(drag.crop,dx,dy,i.naturalWidth,i.naturalHeight);}
function up(event:PointerEvent){if(drag&&drag.id===event.pointerId){move(event);drag=undefined;}}
function keys(event:KeyboardEvent,resize=false){if(props.busy||!image.value)return;const step=event.shiftKey?10:1,dx=event.key==='ArrowRight'?step:event.key==='ArrowLeft'?-step:0,dy=event.key==='ArrowDown'?step:event.key==='ArrowUp'?-step:0;if(!dx&&!dy)return;event.preventDefault();event.stopPropagation();const i=image.value;
 crop.value=resize?resizeIconCrop(crop.value,crop.value.width+dx+(ratio.value?dy*ratio.value:0),crop.value.height+dy,i.naturalWidth,i.naturalHeight,ratio.value):moveIconCrop(crop.value,dx,dy,i.naturalWidth,i.naturalHeight);}
function apply(){if(!image.value||!preview.value)return;try{emit('apply',renderIconCrop(image.value,crop.value,preview.value,removal.value));}catch(e){error.value=e instanceof Error?e.message:'图标处理失败。';}}
</script>
<template><ModalDialog title="裁剪图标" :close-disabled="busy" @close="emit('close')">
 <div class="icon-crop-dialog"><p class="crop-name">{{name}}</p><label class="crop-ratio">裁剪比例<select v-model="shape" aria-label="图标裁剪比例" :disabled="busy"><option value="square">方形 1:1</option><option value="original">原图比例</option><option value="landscape">横向 4:3</option><option value="portrait">纵向 3:4</option><option value="free">自由比例</option></select></label>
 <p class="settings-note">拖动选框移动位置，拖动右下角调整大小。方向键可微调，Shift＋方向键移动更快。</p>
 <div class="crop-layout"><div class="crop-surface" :class="{'picking-color':sampling}" data-background-surface @click.capture="sample"><img ref="image" :src="url" alt="待裁剪的图标原图" draggable="false" @load="loaded"/><div v-if="ready" class="crop-selection" :style="selection" role="group" aria-label="图标裁剪区域" tabindex="0" @pointerdown="down($event)" @pointermove="move" @pointerup="up" @pointercancel="drag=undefined" @keydown="keys($event)"><span class="crop-grid"/><button type="button" class="crop-resize" aria-label="调整图标裁剪大小" :disabled="busy" @pointerdown="down($event,true)" @pointermove.stop="move" @pointerup.stop="up" @pointercancel="drag=undefined" @keydown="keys($event,true)">↘</button></div></div><div class="crop-preview" data-background-surface><canvas ref="preview" aria-label="裁剪后的图标预览"/><span>图标预览</span></div></div>
 <label class="crop-remove-toggle"><input v-model="removeBackground" type="checkbox" :disabled="busy"/>移除纯色背景</label>
 <div v-if="removeBackground" class="crop-background-controls"><input type="color" aria-label="要移除的背景颜色色盘" :value="backgroundColor" :disabled="busy" @input="setColor(($event.target as HTMLInputElement).value)"/><input v-model="colorDraft" aria-label="要移除的背景 HEX 颜色" maxlength="7" :disabled="busy" @change="setColor(colorDraft)"/><button :aria-pressed="sampling" :disabled="busy" @click="sampling=!sampling">{{sampling?'取消背景取色':'点击原图取色'}}</button><label>色差容差 {{tolerance}}<input v-model.number="tolerance" type="range" min="0" max="80" aria-label="背景颜色容差" :disabled="busy"/></label><p v-if="sampling" class="settings-note">点击原图中的纯色背景。</p><p class="settings-note">默认移除白色。清除与图片边缘连通的所选底色，保留内部不相连的同色部分。</p></div>
 <p class="settings-note">非方形裁剪会等比例居中放入图标，保留透明留白。</p><p v-if="error||saveError" role="alert">{{error||saveError}}</p>
 </div><template #footer><button :disabled="busy" @click="emit('pick')">重新选择图片</button><button :disabled="busy" @click="reset">重置裁剪</button><button :disabled="busy" @click="emit('close')">取消</button><button class="primary" :disabled="busy||!ready" @click="apply">{{busy?'保存中…':'应用裁剪'}}</button></template>
</ModalDialog></template>
<style scoped>
.crop-remove-toggle{display:flex;gap:8px;align-items:center}.crop-background-controls{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.crop-background-controls input[type=color]{width:42px;height:34px;padding:3px}.crop-background-controls input:not([type=color]):not([type=range]){width:104px}.crop-background-controls label{display:grid;gap:4px;flex:1;min-width:140px;font-size:.85rem}.crop-background-controls p{width:100%}.picking-color,.picking-color .crop-selection{cursor:crosshair}
.icon-crop-dialog{display:grid;gap:12px}.crop-name{overflow-wrap:anywhere;font-size:.9rem;color:var(--muted)}.crop-ratio{display:flex;align-items:center;gap:12px}.crop-ratio select{flex:1;min-width:0}.crop-layout{display:flex;gap:18px;align-items:center;justify-content:center;flex-wrap:wrap}.crop-surface{position:relative;max-width:100%;width:fit-content;overflow:hidden;border-radius:6px;line-height:0}.crop-surface>img{display:block;max-width:100%;max-height:330px;width:auto;height:auto;user-select:none}.crop-selection{position:absolute;border:2px solid var(--accent);box-shadow:0 0 0 1000px rgba(0,0,0,.45);cursor:move;touch-action:none}.crop-grid{position:absolute;inset:0;pointer-events:none;background:linear-gradient(to right,transparent 33%,#ffffff60 33%,#ffffff60 33.5%,transparent 33.5%,transparent 66%,#ffffff60 66%,#ffffff60 66.5%,transparent 66.5%),linear-gradient(to bottom,transparent 33%,#ffffff60 33%,#ffffff60 33.5%,transparent 33.5%,transparent 66%,#ffffff60 66%,#ffffff60 66.5%,transparent 66.5%)}.crop-resize{position:absolute;right:0;bottom:0;width:22px;min-width:22px;height:22px;min-height:22px;padding:0;cursor:nwse-resize;touch-action:none;line-height:1}.crop-preview{display:grid;gap:8px;justify-items:center;padding:12px;border:1px solid var(--border);border-radius:8px}.crop-preview canvas{width:88px;height:88px;background:repeating-conic-gradient(#dddddd 0% 25%,#ffffff 0% 50%) 0/12px 12px}.crop-preview span{font-size:.8rem;color:var(--muted)}
</style>
